sp_widget.client_script:
api.controller = function($scope) {

    var c = this;
    c.activeSection = 'section1';
    var parent_form = $scope.page.g_form;

    c.showSection = function(sectiontype) {

        if (sectiontype == 'section1') {

            c.activeSection = 'section1';
            parent_form.setDisplay('please_enter_the_manager_s_name', true);
            parent_form.setDisplay('please_enter_the_applicant_s_name', true);
            parent_form.setDisplay('please_chiose_laptop_type', false);
            parent_form.setDisplay('please_enter_the_remark', false);

        } else {

            c.activeSection = 'section2';
            parent_form.setDisplay('please_enter_the_manager_s_name', false);
            parent_form.setDisplay('please_enter_the_applicant_s_name', false);
            parent_form.setDisplay('please_chiose_laptop_type', true);
            parent_form.setDisplay('please_enter_the_remark', true);
        }

    }

}

sp_widget.css:
.btn-breadcrumb .btn:not(:last-child):after {
  content: " ";
  display: block;
  width: 0;
  height: 0;
  border-top: 17px solid transparent;
  border-bottom: 17px solid transparent;
  border-left: 10px solid white;
  position: absolute;
  top: 50%;
  margin-top: -17px;
  left: 100%;
  z-index: 3;
}
.btn-breadcrumb .btn:not(:last-child):before {
  content: " ";
  display: block;
  width: 0;
  height: 0;
  border-top: 17px solid transparent;
  border-bottom: 17px solid transparent;
  border-left: 10px solid rgb(173, 173, 173);
  position: absolute;
  top: 50%;
  margin-top: -17px;
  margin-left: 1px;
  left: 100%;
  z-index: 3;
}

/** The Spacing **/

.btn-breadcrumb .btn {
  padding:6px 12px 6px 24px;
  font-size:16px;
}
.btn-breadcrumb .btn:first-child {
  padding:6px 6px 6px 10px;
}
.btn-breadcrumb .btn:last-child {
  padding:6px 18px 6px 24px;
}

/** Default button **/
.btn-breadcrumb .btn.btn-default:not(:last-child):after {
  border-left: 10px solid #fff;
}
.btn-breadcrumb .btn.btn-default:not(:last-child):before {
  border-left: 10px solid #ccc;
}
.btn-breadcrumb .btn.btn-default:hover:not(:last-child):after {
  border-left: 10px solid #ebebeb;
}
.btn-breadcrumb .btn.btn-default:hover:not(:last-child):before {
  border-left: 10px solid #adadad;
}
.btn-breadcrumb .btn.btn-default:focus {
 border-left: 10px solid #adadad;
  button-background-color: #54F5FB;
	    color: #54F5FB;
}

.btn-primary {
  background-color: #0000ff;
}
